select sum(o.gross_amount) settled_gross_by_pay_month, sum(p.amount) amt
from orders o join payments p using(order_id)
where p.status='settled' and p.payment_date>='2026-02-01' and p.payment_date<'2026-03-01'

select sum(o.gross_amount) settled_gross_by_pay_date, sum(p.amount) amt
from orders o join payments p using(order_id)
where p.status='settled' and p.payment_date between '2026-01-01' and '2026-03-31'

select sum(o.gross_amount - o.discount_amount) net_by_order_date, count(*) n, sum(p.amount) pay_amt, sum(o.gross_amount) gross
from orders o join payments p using(order_id)
where p.status='settled' and o.order_date between '2026-01-01' and '2026-06-30'

select sum(o.gross_amount - o.discount_amount) net_by_pay_date, count(*) n, sum(p.amount) pay_amt
from orders o join payments p using(order_id)
where p.status='settled' and p.payment_date between '2026-01-01' and '2026-06-30'

select sum(o.gross_amount - o.discount_amount) net_order_month, sum(o.gross_amount) gross, sum(o.discount_amount) disc, count(*) n, sum(p.amount) pay_amt
from orders o join payments p using(order_id)
where p.status='settled' and o.order_date between '2026-02-01' and '2026-02-28'

select sum(o.gross_amount - o.discount_amount) net_paydate, count(*) n
from orders o join payments p using(order_id)
where p.status='settled' and p.payment_date between '2026-02-01' and '2026-02-28'
